    if (!el || !dropdown || dropdown.classList.contains(ROLE_DROPDOWN_PORTAL_CLASS)) return;
    dropdown.classList.add(ROLE_DROPDOWN_PORTAL_CLASS);
    document.body.appendChild(dropdown);
