        var salesRate = sp.rate != null ? (Math.round(Number(sp.rate) * 10000) / 100) + '%' : '';
        if (sp.scopeType === 'role') parts.push('扣除方(销售额' + (salesRate ? ' ' + salesRate : '') + ') ' + (sp.roles || []).join('/'));
        else parts.push('扣除方(销售额' + (salesRate ? ' ' + salesRate : '') + ') 指定员工');
