          id: emp.id,
          name: emp.name,
          role: emp.role,
          matched: false,
          salesAmount: roundMoney(S),
          rate: 0,
          due: 0,
          actual: 0,
          tipBefore: tipBefore,
          tipAfter: tipBefore,
