  doc.write('</tbody></table>');
  doc.write('<div class="hint">Please press <b>Ctrl + P</b>, then select <b>"Save as PDF"</b> to download.</div>');
  doc.write('</body></html>');
  doc.close();

  setTimeout(function() { win.print(); }, 500);
  showNotification('PDF 预览已打开，请在弹出窗口中保存为 PDF', 'success');
