    function getRoleEmployeesForStore(storeName) {
      if (!window.TipOutRosterDirectory || !TipOutRosterDirectory.listEmployees) return fallbackRoleEmployees;
      var grouped = {};
      TipOutRosterDirectory.listEmployees(storeName).forEach(function(employee) {
        if (!grouped[employee.role]) grouped[employee.role] = [];
        grouped[employee.role].push(employee.name);
      });
      if (detailSavedSnapshot && detailSavedSnapshot.store === storeName) detailSavedSnapshot.pools.forEach(function(pool) {
        pool.employees.forEach(function(employee) { if (!grouped[employee.role]) grouped[employee.role] = []; if (grouped[employee.role].indexOf(employee.name) < 0) grouped[employee.role].push(employee.name); });
      });
      return grouped;
    }

    function formatRuleDistribution(rule) {
      if (window.ruleData && ruleData.formatDistributionName) return ruleData.formatDistributionName(rule || {});
      var names = { average: '按员工数量平均分配', hours: '按工作时长占比分配', orders: '按订单占比分配' };
      rule = rule || {};
      var base = names[rule.distribution] || rule.distribution || '—';
      if (rule.distribution !== 'hours') return base;
      var cfg = rule.workHoursConfig || {};
      var max = Number(cfg.maxHoursPerDay);
      if (cfg.mode === 'capped' && isFinite(max) && max >= 0.1 && max <= 24 && Math.round(max * 10) === max * 10) {
        return base + '（每日最多 ' + max + ' 小时）';
      }
      return base + (rule.clockin === 'noclock' ? '（按照实际录入工时）' : '（按照实际打卡工时）');
    }

    function detailManualHoursKey(ruleId, dateKey, employeeName) {
      return String(ruleId) + '|' + String(dateKey) + '|' + String(employeeName);
    }

    function getDetailEmployeeHours(rule, ruleId, dateKey, employeeName) {
      if (rule && rule.clockin === 'noclock') {
        var saved = window.TipOutManualHours && TipOutManualHours.get(ruleId, dateKey, employeeName);
        return parseHoursInput(saved && saved.hours);
      }
      var attendance = (window.TipOutAttendance && TipOutAttendance.getDayStatus)
        ? TipOutAttendance.getDayStatus(employeeName, dateKey)
        : { hours: 0 };
      var hours = parseHoursInput(attendance && (attendance.effectiveHours === undefined ? attendance.hours : attendance.effectiveHours));
      return window.TipAllocation ? TipAllocation.getEffectiveHours({ hours: hours }, rule) : hours;
    }

    function buildDetailEmployees(rule, ruleId, dateKey) {
      var out = [];
      var roleEmployees = getRoleEmployeesForStore(rule && rule.store);
      Object.keys(roleEmployees).forEach(function(role) {
        (roleEmployees[role] || []).forEach(function(name) {
          var fact = window.TipOutScenarioSource ? window.TipOutScenarioSource.employee(name,dateKey,{storeId:rule.store}) : null;
          out.push({ name: name, role: role, hours: getDetailEmployeeHours(rule, ruleId, dateKey, name),
            clockedIn: window.TipOutAttendanceLabel.inspect(name,dateKey).status !== 'absent', orderCount: fact ? fact.orders.length : 0 });
        });
      });
      return out;
    }

